package com.adconnect.chat.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;

import java.time.Instant;

public final class ChatDtos {

    private ChatDtos() {
    }

    public record StartConversationRequest(@NotNull Long participantId, Long dealId) {
    }

    /**
     * @param clientMessageId generated by the client (UUID) and reused on every retry of the same message
     */
    public record SendMessageRequest(
            @NotBlank @Size(max = 64) @Pattern(regexp = "^[A-Za-z0-9-_]+$") String clientMessageId,
            @NotBlank @Size(max = 4000) String content) {
    }

    public record WsSendMessage(@NotBlank String conversationId, @NotBlank String clientMessageId,
                                @NotBlank String content) {
    }

    public record WsTyping(@NotBlank String conversationId) {
    }

    public record TypingEvent(String conversationId, Long userId, String name) {
    }

    public record ConversationDto(String id, Long otherUserId, String otherUserName, Long dealId,
                                  String lastMessagePreview, Long lastSenderId, Instant lastMessageAt, int unread) {
    }

    public record MessageDto(String id, String conversationId, Long senderId, String senderName, String content,
                             String clientMessageId, Instant createdAt) {
    }

    /** Result of a send: {@code replayed} is true when the clientMessageId had already been stored. */
    public record SendResult(MessageDto message, boolean replayed) {
    }

    public record UnreadDto(int total) {
    }
}
